from author import add, save, write
write('applications/logtool/main.mjs', '''
import {parseArgs} from 'node:util';import {createReadStream,createWriteStream} from 'node:fs';import {pipeline} from 'node:stream/promises';import {rename,rm} from 'node:fs/promises';import {randomUUID} from 'node:crypto';import {NDJSON} from '../../shared/ndjson.mjs';
const controller=new AbortController();process.once('SIGINT',()=>controller.abort(Error('Interrupted')));let partial;
try{const {values}=parseArgs({options:{input:{type:'string'},output:{type:'string'},level:{type:'string',default:'info'},malformed:{type:'string',default:'fail'},'max-length':{type:'string',default:'4096'}}});const levels={debug:0,info:1,warn:2,error:3},maxLength=Number(values['max-length']);if(!(values.level in levels)||!['fail','skip','count'].includes(values.malformed)||!Number.isInteger(maxLength)||maxLength<1||maxLength>1000000){process.exitCode=2;throw Error('Usage: --input FILE --output FILE --level info --malformed fail|skip|count --max-length 4096');}const transform=new NDJSON({maxLength,malformed:values.malformed,filter:row=>typeof row==='object'&&row!==null&&(levels[row.level]??-1)>=levels[values.level]});const input=values.input?createReadStream(values.input):process.stdin;let output=process.stdout;if(values.output){partial=values.output+'.'+randomUUID()+'.tmp';output=createWriteStream(partial,{flags:'wx'});}await pipeline(input,transform,output,{signal:controller.signal});if(values.output){await rename(partial,values.output);partial=undefined;}const summary=JSON.stringify({...transform.counts,peakRssKiB:process.resourceUsage().maxRSS});if(values.output)console.log(summary);else console.error(summary);}catch(error){if(partial)await rm(partial,{force:true});console.error(controller.signal.aborted?'Interrupted; incomplete output removed':error.message);process.exitCode=controller.signal.aborted?130:(process.exitCode||1);}
''')
write('applications/logtool/create-fixture.mjs', '''
import {createWriteStream} from 'node:fs';import {once} from 'node:events';import {finished} from 'node:stream/promises';
const mib=Number(process.argv[2]??8);if(!Number.isInteger(mib)||mib<1||mib>1024)throw Error('Choose 1..1024 MiB');const stream=createWriteStream(process.argv[3]??'fixture.ndjson',{flags:'wx'}),line=JSON.stringify({level:'info',message:'course fixture'})+'\\n';let bytes=0,records=0;while(bytes<mib*1024*1024){if(!stream.write(line))await once(stream,'drain');bytes+=Buffer.byteLength(line);records++;}stream.end();await finished(stream);console.log({bytes,records});
''')
add(151,'''import {assert,fs,temp,join,spawnNode} from '../../shared/lab.mjs';import {fileURLToPath} from 'node:url';await using lab=await temp();const input=join(lab.path,'input.ndjson'),output=join(lab.path,'filtered.ndjson');await fs.writeFile(input,'{"level":"debug"}\\n{"level":"info","text":"café 😀"}\\nmalformed\\n{"level":"error"}');const main=fileURLToPath(new URL('../../applications/logtool/main.mjs',import.meta.url));const success=await spawnNode([main,'--input',input,'--output',output,'--level','info','--malformed','count']);assert.equal(success.code,0,success.stderr);const summary=JSON.parse(success.stdout);assert.equal(summary.accepted,2);assert.equal(summary.malformed,1);const before=await fs.readFile(output,'utf8');const failure=await spawnNode([main,'--input',input,'--output',output,'--malformed','fail']);assert.equal(failure.code,1);assert.equal(await fs.readFile(output,'utf8'),before);assert.equal((await fs.readdir(lab.path)).filter(x=>x.endsWith('.tmp')).length,0);console.log(success.stdout,before,'malformed failure preserved existing output and removed partial');''','The complete streaming CLI filters records, counts malformed data, handles a final line without newline, and atomically preserves an existing output on failure.','Run node applications/logtool/main.mjs --input FILE --output RESULT --level info --malformed count from the workspace. Use create-fixture.mjs for an optional 1 GiB benchmark; record peak RSS and select a documented memory budget rather than assuming one.')
add(152,'''import {pgLab} from '../../shared/postgres.mjs';import {buildTaskApi,registerAndLogin} from '../../shared/task-api.mjs';import {randomBytes} from 'node:crypto';import assert from 'node:assert/strict';await using db=await pgLab();let fail=false;const app=await buildTaskApi({pool:db.pool,key:randomBytes(32),afterFirstInsert:async()=>{if(fail)throw Error('injected transaction failure');}});try{const a=await registerAndLogin(app,'a@course.invalid'),b=await registerAndLogin(app,'b@course.invalid');const made=await app.inject({method:'POST',url:'/tasks',headers:a.headers,payload:{title:'capstone'}});assert.equal(made.statusCode,201);const task=made.json();assert.equal((await app.inject({url:'/tasks/'+task.id,headers:b.headers})).statusCode,404);const updates=await Promise.all(['A','B'].map(title=>app.inject({method:'PATCH',url:'/tasks/'+task.id,headers:a.headers,payload:{title,version:0}})));assert.deepEqual(updates.map(x=>x.statusCode).sort(),[200,409]);const before=(await db.pool.query('SELECT count(*) FROM tasks')).rows[0].count;fail=true;assert.equal((await app.inject({method:'POST',url:'/tasks/batch',headers:a.headers,payload:{titles:['one','two']}})).statusCode,500);assert.equal((await db.pool.query('SELECT count(*) FROM tasks')).rows[0].count,before);console.log('authentication, owner isolation, concurrency and injected rollback verified');}finally{await app.close();}''','A complete task API registers/logs in real users, enforces ownership, rejects stale edits and rolls back an injected batch failure.','The standalone server, schema migration and container deployment are in applications/task-api and deployment. Use the Docker rehearsal in Prompt 155 for browser/manual HTTP access. Passwords use versioned scrypt records; bearer tokens are never printed.',mode='postgres',deps=['fastify','pg','jose'])
add(154,'''import {Queue,QueueEvents,Worker} from 'bullmq';import {fork} from 'node:child_process';import {randomUUID} from 'node:crypto';import {pgLab} from '../../shared/postgres.mjs';import {redisConnection} from '../../shared/redis.mjs';import {createReport,publishResult} from '../../shared/outbox.mjs';import assert from 'node:assert/strict';await using db=await pgLab();await createReport(db.pool,'crash-report');const name='crash-'+randomUUID(),connection=redisConnection(),queue=new Queue(name,{connection}),events=new QueueEvents(name,{connection});events.on('error',()=>{});await events.waitUntilReady();let recovery,child;try{child=fork(new URL('./crash-worker.mjs',import.meta.url),{env:{...process.env,COURSE_SCHEMA:db.schema,COURSE_QUEUE:name},stdio:['ignore','inherit','inherit','ipc']});await new Promise((resolve,reject)=>{child.once('message',resolve);child.once('error',reject);});const exited=new Promise(resolve=>child.once('exit',resolve));const job=await queue.add('report',{reportId:'crash-report'},{attempts:3,backoff:{type:'exponential',delay:10}});assert.equal(await exited,99);recovery=new Worker(name,job=>publishResult(db.pool,job.data.reportId,job.data.reportId),{connection,lockDuration:1000,stalledInterval:500,maxStalledCount:2});recovery.on('error',()=>{});await job.waitUntilFinished(events,15000);assert.equal((await db.pool.query('SELECT count(*) FROM processed_events')).rows[0].count,'1');assert.equal((await db.pool.query('SELECT status FROM reports')).rows[0].status,'complete');console.log('worker exited 99 after commit; stalled job retried; one durable business result');}finally{if(child?.connected)child.kill();await recovery?.close();await queue.obliterate({force:true});await events.close();await queue.close();}''','A separate worker process really exits after publishing its result but before ACK. Recovery retries the stalled job and the database proves one durable effect.',files={'crash-worker.mjs':"import {Worker} from 'bullmq';import {Pool} from 'pg';import {redisConnection} from '../../shared/redis.mjs';import {publishResult} from '../../shared/outbox.mjs';if(!/^lab_[a-f0-9]+$/.test(process.env.COURSE_SCHEMA??''))throw Error('Invalid lab schema');const pool=new Pool({connectionString:process.env.DATABASE_URL,options:'-c search_path='+process.env.COURSE_SCHEMA});const worker=new Worker(process.env.COURSE_QUEUE,async job=>{await publishResult(pool,job.data.reportId,job.data.reportId);process.exit(99);},{connection:redisConnection(),lockDuration:1000,stalledInterval:500,maxStalledCount:2});worker.on('error',()=>{});await worker.waitUntilReady();process.send('ready');"},mode='postgres+redis',deps=['pg','bullmq'])
add(155,'''import {deploymentDemo} from '../../shared/deployment-demo.mjs';await deploymentDemo('full');''','The real Compose deployment serves two API replicas behind NGINX, completes a BullMQ report, exposes metrics and survives API replacement.','This integration rehearsal builds images and starts a separate local Docker project. It shuts that project down afterward while retaining named volumes. Review deployment/README.md for metrics/traces, rollback, backup and outage rehearsals.',mode='docker')
